"""Write docs/RESULTS.md from results/test (tables only, no interpretation)."""
import json
from pathlib import Path

import pandas as pd

R = Path("results/test")
S = json.load(open(R / "summary.json"))
DETS = ["owlvit", "owlv2", "colour"]
NAMES = {"owlvit": "OWL-ViT", "owlv2": "OWLv2", "colour": "Colour rule"}


def curve(det, method, iou, kind="fixed"):
    return pd.read_csv(R / f"curve_{det}_{method}_iou{iou}_{kind}.csv")


def f(x, nd=1):
    return "-" if x is None or pd.isna(x) else f"{x:.{nd}f}"


out = ["# Held-out test results", "",
       "Generated by `scripts/make_results_md.py` from `results/test`. 400 test chips, "
       "Paris and Khartoum, frozen settings from `configs/frozen.yaml`. F1 in percent, "
       "95% block-bootstrap intervals.", ""]
for iou in (0.25, 0.5):
    for method in ("area", "blur_resize"):
        out += [f"## F1 vs resolution, IoU {iou}, {method}", "",
                "| GSD (m) | " + " | ".join(NAMES[d] + " F1 [95% CI]" for d in DETS) +
                " | OWL-ViT chance | OWLv2 chance | Colour chance |",
                "|---|" + "---|" * (len(DETS) * 2), ]
        cs = {d: curve(d, method, iou) for d in DETS}
        for i, lv in enumerate(cs["owlvit"]["levels"]):
            cells = [f"{f(cs[d].f1[i])} [{f(cs[d].lo[i])}, {f(cs[d].hi[i])}]" for d in DETS]
            ch = [f(cs[d].chance[i]) for d in DETS]
            out.append(f"| {lv:g} | " + " | ".join(cells) + " | " + " | ".join(ch) + " |")
        out.append("")
out += ["## Break points (F1 falls to half of its peak above chance)", "",
        "| Detector | Method | IoU | Setting | Peak GSD | Peak F1 | Break GSD [95% CI] | Break vs finest level |",
        "|---|---|---|---|---|---|---|---|"]
for k, v in S.items():
    det, method, iou, kind = k.split("|")
    ci = v.get("break_ci")
    out.append(f"| {NAMES[det]} | {method} | {iou[3:]} | {kind} | {v['peak_level']:g} | {f(v['peak_f1'])} | "
               f"{f(v['break_point'], 2)} [{f(ci[0], 2) if ci else '-'}, {f(ci[1], 2) if ci else '-'}] | "
               f"{f(v['break_point_finest_ref'], 2)} |")
out.append("")
rs = pd.read_csv("results/test_real_sensor/real_sensor.csv")
out += ["## Native 1.2 m multispectral vs simulated 1.2 m (same 400 chips)", "",
        "| Detector | IoU | Simulation | Native F1 | Simulated F1 | Native minus simulated [95% CI] |",
        "|---|---|---|---|---|---|"]
for _, r in rs.iterrows():
    ci = json.loads(r.diff_ci) if isinstance(r.diff_ci, str) else r.diff_ci
    out.append(f"| {NAMES[r.detector]} | {r.iou} | {r.sim_method} | {f(r.native_f1)} | {f(r.sim_f1)} | "
               f"{f(r.diff_native_minus_sim)} [{f(ci[0])}, {f(ci[1])}] |")
out.append("")


def parse_ci(x):
    return json.loads(x) if isinstance(x, str) else x


def curve_table(folder, title, method="area", iou=0.25):
    d = Path(folder)
    if not (d / f"curve_owlvit_{method}_iou{iou}_fixed.csv").exists():
        return []
    cs = {x: pd.read_csv(d / f"curve_{x}_{method}_iou{iou}_fixed.csv") for x in DETS}
    t = [f"## {title}", "",
         "| GSD (m) | " + " | ".join(NAMES[x] + " F1 [95% CI]" for x in DETS) + " |",
         "|---|---|---|---|"]
    for i, lv in enumerate(cs["owlvit"]["levels"]):
        t.append(f"| {lv:g} | " + " | ".join(
            f"{f(cs[x].f1[i])} [{f(cs[x].lo[i])}, {f(cs[x].hi[i])}]" for x in DETS) + " |")
    return t + [""]


for iou in (0.25, 0.5):
    for method in ("area", "blur_resize"):
        p = R / f"oracle_diff_{method}_iou{iou}.csv"
        if not p.exists():
            continue
        o = pd.read_csv(p)
        out += [f"## Detector F1 against the oracle-location baseline, IoU {iou}, {method}", "",
                "The oracle keeps each detector's box count and sizes and moves the boxes onto random "
                "true building centres. Difference is detector minus oracle, with a block-bootstrap interval.", "",
                "| Detector | Setting | GSD (m) | F1 | Oracle F1 | Difference [95% CI] |", "|---|---|---|---|---|---|"]
        for _, r in o.iterrows():
            out.append(f"| {NAMES[r.detector]} | {r.kind} | {r.level:g} | {f(r.f1)} | {f(r.oracle_f1)} | "
                       f"{f(r['diff'])} [{f(r.lo)}, {f(r.hi)}] |")
        out.append("")
out += curve_table("results/vegas", "Third city (Las Vegas, 200 chips, never used for tuning), IoU 0.25, area")
out += curve_table("results/vegas", "Third city (Las Vegas), IoU 0.25, blur_resize", method="blur_resize")
pc = Path("results/per_city.csv")
if pc.exists():
    c = pd.read_csv(pc)
    out += ["## Per-city peak and break point, frozen settings, IoU 0.25", "",
            "| City | Detector | Method | Chips | Peak GSD | Peak F1 | Break GSD [95% CI] | F1 at 2.4 m | F1 at 3.6 m |",
            "|---|---|---|---|---|---|---|---|---|"]
    for _, r in c.iterrows():
        out.append(f"| {r.city} | {NAMES[r.detector]} | {r.method} | {r.n_chips} | {r.peak_gsd:g} | "
                   f"{f(r.peak_f1)} | {f(r.break_gsd, 2)} [{f(r.break_lo, 2)}, {f(r.break_hi, 2)}] | "
                   f"{f(r['f1_2.4'])} | {f(r['f1_3.6'])} |")
    out.append("")
for folder, label in (("results/test_sentinel2", "Paris and Khartoum"), ("results/vegas_sentinel2", "Las Vegas")):
    p = Path(folder) / "sentinel2.csv"
    if not p.exists():
        continue
    s2 = pd.read_csv(p)
    out += [f"## Real Sentinel-2 vs simulated 10 m, {label} ({int(s2.n_chips.iloc[0])} chips)", "",
            "Same chip footprints and labels. Sentinel-2 L2A crops (20 by 20 px), upsampled like the simulation. "
            "Oracle F1 is the oracle-location baseline on the real crops.", "",
            "| Detector | Setting | IoU | Simulation | Real S2 F1 [95% CI] | Simulated F1 [95% CI] | Real minus simulated [95% CI] | Oracle F1 |",
            "|---|---|---|---|---|---|---|---|"]
    for _, r in s2.iterrows():
        a, b, dci = parse_ci(r.s2_ci), parse_ci(r.sim_ci), parse_ci(r.diff_ci)
        out.append(f"| {NAMES[r.detector]} | {r.setting} | {r.iou} | {r.sim_method} | "
                   f"{f(r.s2_f1)} [{f(a[0])}, {f(a[1])}] | {f(r.sim_f1)} [{f(b[0])}, {f(b[1])}] | "
                   f"{f(r.diff_s2_minus_sim)} [{f(dci[0])}, {f(dci[1])}] | {f(r.oracle_f1_on_s2)} |")
    out.append("")
Path("docs/RESULTS.md").write_text("\n".join(out) + "\n")
print("wrote docs/RESULTS.md")
